            Member m = shown.get(i);
            cut.add(new Member(m.personId(), m.pool(), m.name(), m.share(), m.retired(), cuts.get(i)));
        }
        return cut;
    }

    /** Add a pool under its name, trimmed; refused when the name is blank, too long or already a pool's. */
    @Transactional
